// SET THIS to your WhatsApp Business number in international format, digits only.
// Example for India: 919876543210 (do not include +, spaces, or dashes).
const BUSINESS_WHATSAPP = "";
function sendOrderToWhatsApp(order) {
  if (!/^\d{10,15}$/.test(BUSINESS_WHATSAPP)) return;
  const lines = [
    `New Label Awadh order #${order.id}`,
    `Customer: ${order.addr.name}`,
    `Phone: ${order.addr.phone}`,
    `Address: ${order.addr.line}, ${order.addr.area}, ${order.addr.city}, ${order.addr.state} - ${order.addr.pin}`,
    ...order.items.map(item => { const p = byId(item.id); return `${p.name} | Size ${item.size} | Qty ${item.qty} | ₹${item.price * item.qty}`; }),
    `Total: ₹${order.total}`,
    `Payment: ${order.pay}`
  ];
  window.open(`https://wa.me/${BUSINESS_WHATSAPP}?text=${encodeURIComponent(lines.join('\n'))}`, '_blank', 'noopener,noreferrer');
}


