  set:{d:"M64 32 L88 24 Q100 46 112 24 L136 32 L168 82 L150 94 L138 80 L145 194 L55 194 L62 80 L50 94 L32 82 Z",hem:[184,60,140],vine:160,neck:1,pants:"M60 160 L140 160 L154 240 L108 240 L100 186 L92 240 L46 240 Z",dvb:"60 16 80 100"},
  anarkali:{d:"M70 30 L88 24 Q100 44 112 24 L130 30 L166 84 L150 96 L134 82 L128 100 L176 228 L24 228 L72 100 L66 82 L50 96 L34 84 Z",hem:[214,34,166],vine:98,neck:1,hem2:1,dvb:"60 16 80 100"},
