let AN=0;
function fl(x,y,s){let o="";for(let i=0;i<5;i++)o+=`<ellipse cx="${x}" cy="${(y-2.3*s).toFixed(2)}" rx="${(1.1*s).toFixed(2)}" ry="${(2.1*s).toFixed(2)}" transform="rotate(${i*72} ${x} ${y})"/>`;return o+`<circle cx="${x}" cy="${y}" r="${(.8*s).toFixed(2)}" opacity=".6"/>`}
function lf(x,y,s,a){return `<ellipse cx="${x}" cy="${y}" rx="${(.8*s).toFixed(2)}" ry="${(2*s).toFixed(2)}" transform="rotate(${a} ${x} ${y})"/>`}
function butiPat(id,T,scale=1){return `<pattern id="${id}" width="26" height="30" patternUnits="userSpaceOnUse" patternTransform="scale(${scale})"><g fill="${T}" opacity=".85">${fl(13,9,1.05)+lf(9.6,15.4,1,-40)+lf(16.4,15.4,1,40)+fl(0,24,.6)+fl(26,24,.6)}</g></pattern>`}
function neckWork(T,vineEnd){
  let o="";
  for(let i=0;i<=8;i++){const t=i/8,x=(1-t)*(1-t)*80+2*(1-t)*t*100+t*t*120,y=(1-t)*(1-t)*34+2*(1-t)*t*74+t*t*34;o+=fl(+x.toFixed(1),+y.toFixed(1),.72)}
  o+=fl(100,64,1.9)+lf(91.5,70,1.3,-55)+lf(108.5,70,1.3,55);
  if(vineEnd>84){
    o+=`<path d="M100 74 Q96 ${(74+vineEnd)/2} 100 ${vineEnd}" fill="none" stroke="${T}" stroke-width="1" stroke-dasharray="2.2 1.6"/>`;
    for(let y=84,k=0;y<vineEnd-4;y+=12,k++)o+=lf(k%2?104.5:95.5,y,1,k%2?40:-40);
    o+=fl(100,vineEnd+2,1.1);
  }
  return `<g fill="${T}" opacity=".92">${o}</g>`;
}
function hemWork(T,[y,l,r],big){
  let o="";const step=big?10:8.5;
  for(let x=l+5;x<=r-4;x+=step)o+=fl(+x.toFixed(1),y,big?1:.78);
  if(big)for(let x=l+10;x<=r-8;x+=step)o+=fl(+x.toFixed(1),y-11,.55);
  return `<g fill="${T}" opacity=".9">${o}</g><path d="M${l} ${y+7} H${r}" stroke="${T}" stroke-width=".9" stroke-dasharray="2.6 1.8" opacity=".8"/>`;
}
function art(p,view="front"){
  if(!p || typeof p!=="object"){return `<div class="pimg-placeholder" role="img" aria-label="Product image unavailable">Product image unavailable</div>`;}

  if(p.image_urls && p.image_urls.length){const src=p.image_urls[Math.min(view==="back"?1:view==="detail"?2:view==="fabric"?3:0,p.image_urls.length-1)]||p.image_urls[0];return `<img src="${esc(src)}" alt="${esc(p.name)}${view!=="front"?", "+view+" view":""}" loading="lazy" style="width:100%;height:100%;object-fit:cover" onerror="this.style.display='none'">`;}
  const u="a"+(++AN),T=p.thread||"#FFFFFF",S=SH[p.shape]||SH.kurta;
  const label=p.name+(view!=="front"?", "+view+" view":"");
  const defs=`<defs>${butiPat(u+"b",T,view==="fabric"?2.6:1)}<linearGradient id="${u}g" x1="0" x2="1"><stop offset="0" stop-color="#000" stop-opacity=".07"/><stop offset=".5" stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".09"/></linearGradient></defs>`;
  if(view==="fabric"){
    return `<svg viewBox="0 0 200 250" preserveAspectRatio="xMidYMid slice" role="img" aria-label="${label}">${defs}<rect width="200" height="250" fill="${p.hex}"/><rect width="200" height="250" fill="url(#${u}b)"/><g fill="${T}" opacity=".95">${fl(100,118,7)+lf(78,140,4.5,-50)+lf(122,140,4.5,50)+lf(84,98,3.4,-120)+lf(116,98,3.4,120)}</g></svg>`;
  }
  const vb=view==="detail"?S.dvb:"-20 0 240 250";
  let b="";
  if(S.pants)b+=`<path d="${S.pants}" fill="${p.pants||p.hex}" stroke="rgba(0,0,0,.12)" stroke-width="1.2"/><path d="${S.pants}" fill="url(#${u}g)"/>`;
  b+=`<path d="${S.d}" fill="${p.hex}" stroke="rgba(0,0,0,.12)" stroke-width="1.4"/><path d="${S.d}" fill="url(#${u}b)"/>`;
  if(S.pallu)b+=`<path d="${S.pallu}" fill="${T}" opacity=".18"/><path d="${S.pallu}" fill="url(#${u}b)"/><path d="M40 150 L160 80" stroke="${T}" stroke-width="1.2" stroke-dasharray="3 2" opacity=".8"/>`;
  b+=`<path d="${S.d}" fill="url(#${u}g)"/>`;
  if(S.neck&&view!=="back")b+=neckWork(T,S.vine);
  b+=hemWork(T,S.hem,S.hem2);
  if(S.top)b+=hemWork(T,S.top,false);
  if(S.tassel){let t="";for(let x=48;x<=152;x+=8)t+=`<path d="M${x} ${228-(Math.abs(x-100)/52)*3} v9" stroke="${p.hex}" stroke-width="2.4" stroke-linecap="round"/><circle cx="${x}" cy="${238-(Math.abs(x-100)/52)*3}" r="1.6" fill="${p.hex}"/>`;b+=`<g opacity=".95">${t}</g>`}
  return `<svg viewBox="${vb}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${label}">${defs}${b}</svg>`;
}

