/* ---------- SHOP ---------- */
function filtered(){
  const f=S.f,words=f.q.toLowerCase().split(/\s+/).filter(Boolean);
  let L=P.filter(p=>{
    if(f.cat.size&&!f.cat.has(p.cat))return false;
    if(f.size.size&&![...f.size].some(s=>!p.free&&!p.sold.includes(s)))return false;
    if(f.colour.size&&!f.colour.has(p.colour))return false;
    if(f.fabric.size&&!f.fabric.has(p.fabric.split(",")[0]))return false;
    if(p.price>f.max)return false;
    if(f.sale&&off(p)<20)return false;
    if(f.neu&&!(p.tag==="New"||p.tag==="Heirloom"))return false;
    const txt=(p.name+" "+p.cat+" "+p.colour+" "+p.fabric+" "+p.stitch+" chikankari").toLowerCase();
    return words.every(w=>txt.includes(w.replace(/s$/,"")));
  });
  const so={pop:(a,b)=>b.reviews-a.reviews,low:(a,b)=>a.price-b.price,high:(a,b)=>b.price-a.price,disc:(a,b)=>off(b)-off(a),rate:(a,b)=>b.rating-a.rating}[f.sort];
  return L.sort(so);
}
function shopTitle(){const f=S.f;if(f.q)return `Results for “${esc(f.q)}”`;if(f.neu)return "New &amp; heirloom";if(f.cat.size===1)return esc([...f.cat][0]);return "The collection"}
function chipsHTML(){
  const f=S.f,c=[];
  if(f.q)c.push(["q","",`“${esc(f.q)}”`]);
  f.cat.forEach(v=>c.push(["cat",v,esc(v)]));f.size.forEach(v=>c.push(["size",v,"Size "+v]));f.colour.forEach(v=>c.push(["colour",v,v]));f.fabric.forEach(v=>c.push(["fabric",v,v]));
  if(f.max<7000)c.push(["max","","Under "+inr(f.max)]);
  if(f.sale)c.push(["sale","","20% off or more"]);if(f.neu)c.push(["neu","","New"]);
  return c.map(([k,v,l])=>`<span class="chip">${l}<button class="link" style="text-decoration:none" data-act="unchip" data-k="${k}" data-v="${esc(v)}" aria-label="Remove filter ${l}">×</button></span>`).join("")+(c.length?`<button class="link" data-act="clearf">Clear all</button>`:"");
}
function vShop(){
  const f=S.f,L=filtered();
  return `<div class="wrap"><div class="crumbs"><button data-act="home">Home</button> / Shop</div>
   <div class="shop">
    <aside class="filters" id="filters" aria-label="Filters">
      <div class="fgroup"><h4>Silhouette</h4><div class="checks">${CATS.map(([c])=>`<label><input type="checkbox" data-f="cat" value="${esc(c)}" ${f.cat.has(c)?"checked":""}>${esc(c)} <span class="muted">(${P.filter(p=>p.cat===c).length})</span></label>`).join("")}</div></div>
      <div class="fgroup"><h4>Size</h4><div class="pills">${ALL.map(s=>`<button class="pill" data-act="fset" data-k="size" data-v="${s}" aria-pressed="${f.size.has(s)}">${s}</button>`).join("")}</div></div>
      <div class="fgroup"><h4>Colour</h4><div class="swatches">${COLOURS.map(([n,h])=>`<button class="sw" style="background:${h}" title="${n}" aria-label="${n}" data-act="fset" data-k="colour" data-v="${n}" aria-pressed="${f.colour.has(n)}"></button>`).join("")}</div></div>
      <div class="fgroup"><h4>Fabric</h4><div class="checks">${FABRICS.map(x=>`<label><input type="checkbox" data-f="fabric" value="${esc(x)}" ${f.fabric.has(x)?"checked":""}>${esc(x)}</label>`).join("")}</div></div>
      <div class="fgroup"><h4>Price</h4><div class="range"><input type="range" id="price" min="1000" max="7000" step="250" value="${f.max}" aria-label="Maximum price"><div class="row" style="justify-content:space-between"><span class="muted">₹1,000</span><b id="priceLbl" class="num">Up to ${inr(f.max)}</b></div></div></div>
      <div class="fgroup"><h4>Offers</h4><div class="checks"><label><input type="checkbox" data-f="sale" ${f.sale?"checked":""}>20% off or more</label><label><input type="checkbox" data-f="neu" ${f.neu?"checked":""}>New &amp; heirloom</label></div></div>
      <div class="fclose"><button class="btn ghost" data-act="clearf" style="flex:1">Clear</button><button class="btn" data-act="fclose" style="flex:2" id="showN">Show ${L.length} results</button></div>
    </aside>
    <section>
      <div class="shopbar"><div><h1>${shopTitle()}</h1><span class="muted" id="nRes">${L.length} pieces</span></div>
        <div class="row"><button class="btn ghost fbtn" data-act="fopen">Filters</button>
        <label class="muted" style="font-size:13px">Sort by <select id="sort">${[["pop","Popularity"],["low","Price: low to high"],["high","Price: high to low"],["disc","Discount"],["rate","Customer rating"]].map(([v,l])=>`<option value="${v}" ${f.sort===v?"selected":""}>${l}</option>`).join("")}</select></label></div></div>
      <div class="chips" id="chips">${chipsHTML()}</div>
      <div id="results">${resultsHTML(L)}</div>
    </section>
   </div></div>`;
}
function resultsHTML(L){return L.length?`<div class="pgrid">${L.map(pcard).join("")}</div>`:`<div class="empty"><h2>No matching pieces</h2><p>Try removing a filter or searching for something else.</p><button class="btn ghost" data-act="clearf">Clear filters</button></div>`}
function refresh(){const L=filtered();$("#results").innerHTML=resultsHTML(L);$("#nRes").textContent=L.length+" pieces";$("#chips").innerHTML=chipsHTML();$("#showN").textContent=`Show ${L.length} results`;document.querySelector(".shopbar h1").innerHTML=shopTitle()}

